window.SCHOOL_LISTENING={"../assets/media/ec16535a4c134bb097704188258191fdf8cf015418f2b819d601d346f2feb75f.mp3":[{"id":"PPT_ec16535a4c134bb0","audioId":"PPT_ec16535a4c134bb0","title":"Book 2 · Unit 6 · RW · READING 2","subtitle":"READING 2 · source slide 120","duration":255.56,"cues":[{"start":0,"end":4.38,"text":"The story of ChatGPT and OpenAI","coverage":1},{"start":5.86,"end":9.32,"text":"ChatGPT is an artificial intelligence, AI,","coverage":1},{"start":9.74,"end":10.26,"text":"technology.","coverage":1},{"start":11.06,"end":15.14,"text":"It can have an online conversation with the person using it.","coverage":1},{"start":15.6,"end":20.34,"text":"It can understand questions and answer them in a way that sounds human,","coverage":1},{"start":20.8,"end":24.38,"text":"and it can even say sorry when it makes a mistake.","coverage":1},{"start":25.8,"end":30.74,"text":"ChatGPT is owned by a technology company called OpenAI.","coverage":1},{"start":31.76,"end":34.48,"text":"The company was set up by Elon Musk,","coverage":1},{"start":34.96,"end":35.8,"text":"Sam Altman,","coverage":1},{"start":36.14,"end":38.12,"text":"and others in 2015.","coverage":1},{"start":39.16,"end":45.1,"text":"Their goal was to build safe AI technology that could be used by everyone.","coverage":1},{"start":45.86,"end":46.4,"text":"Today,","coverage":1},{"start":46.82,"end":50.82,"text":"OpenAI employs 375 people.","coverage":1},{"start":50.82,"end":57.6,"text":"The partners started a company that created the fastest growing application of all time.","coverage":1},{"start":58.36,"end":58.9,"text":"Now,","coverage":1},{"start":59.26,"end":63.66,"text":"OpenAI wants to make more powerful AI technology.","coverage":1},{"start":64.56,"end":69.14,"text":"They believe that more use of AI in the world is a good thing.","coverage":1},{"start":70.62,"end":72.88,"text":"OpenAI grew very quickly.","coverage":1},{"start":73.42,"end":76.78,"text":"The company started with investments of $one billion,","coverage":1},{"start":77.4,"end":83.58,"text":"and in 2016, less than a year later, it developed its first AI program,","coverage":1},{"start":84.2,"end":85.5,"text":"OpenAI Gym.","coverage":1},{"start":86.6,"end":91.82,"text":"In 2018, the company introduced the first version of GPT,","coverage":1},{"start":92.2,"end":99.1,"text":"which was the first time that a machine could make sentences that sounded like they were written by a real person.","coverage":1},{"start":100,"end":109,"text":"This was the same year that Elon Musk left OpenAI, and the company announced it was going to partner with Microsoft Corporation.","coverage":1},{"start":110.16,"end":116.32,"text":"The partnership meant OpenAI could do more research and share the results with the world.","coverage":1},{"start":117.16,"end":118.24,"text":"In 2020,","coverage":1},{"start":118.8,"end":121.66,"text":"OpenAI opened its office in San Francisco.","coverage":1},{"start":122.6,"end":126.74,"text":"It shares the building with another business started by Elon Musk.","coverage":1},{"start":126.74,"end":131.5,"text":"ChatGPT was introduced in November 2022,","coverage":1},{"start":132.28,"end":135.7,"text":"and it grew faster than any other application.","coverage":1},{"start":136.48,"end":138.04,"text":"In only two months,","coverage":1},{"start":138.52,"end":141.12,"text":"100 million people used it.","coverage":1},{"start":141.64,"end":148.9,"text":"About 13 million people used ChatGPT every day in January 2023,","coverage":1},{"start":149.58,"end":152.92,"text":"which is double the number who used it in December.","coverage":1},{"start":153.88,"end":155.84,"text":"Compare this to TikTok,","coverage":1},{"start":156.24,"end":164.2,"text":"which took about nine months to get about 100 million users, and Instagram, which took about two .five","coverage":1},{"start":164.2,"end":164.84,"text":"years.","coverage":1},{"start":166.28,"end":168.52,"text":"ChatGPT is free to use.","coverage":1},{"start":168.76,"end":169.38,"text":"However,","coverage":1},{"start":169.84,"end":171.98,"text":"in February 2023,","coverage":1},{"start":172.56,"end":175.7,"text":"OpenAI started to advertise a subscription.","coverage":1},{"start":176.5,"end":182.9,"text":"People who choose to pay $20 every month get faster answers to their questions.","coverage":1},{"start":183.48,"end":190.12,"text":"Some schools and teachers worry about students using ChatGPT to do their coursework.","coverage":1},{"start":191.02,"end":198.56,"text":"A number of schools in America stopped teachers and students from using the application while they were at school.","coverage":1},{"start":199.2,"end":205.98,"text":"This shows that not everyone is happy about AI technology and how fast it is growing.","coverage":1},{"start":206.68,"end":215.2,"text":"Some people think businesses like OpenAI are not thinking about the possible bad results of the things they are doing.","coverage":1},{"start":216.36,"end":222.86,"text":"OpenAI is still working hard to make amazing AI that can help all people.","coverage":1},{"start":223.46,"end":231.14,"text":"In the future, they want to make AI programs that can do things like help doctors find cures for diseases,","coverage":1},{"start":231.74,"end":238.6,"text":"find answers to difficult problems like climate change, or help people to run their businesses better.","coverage":1},{"start":239.44,"end":243.86,"text":"Although some people worry that in the future AI will hurt people,","coverage":1},{"start":244.42,"end":253.6,"text":"OpenAI wants to make sure that AI will be safe for everyone to use and will make our lives easier and more enjoyable.","coverage":1}],"file":"126535065b1eefbfae94.js","track":0,"media":"../assets/media/ec16535a4c134bb097704188258191fdf8cf015418f2b819d601d346f2feb75f.mp3"}],"../assets/media/6f42171301964649b084cefeb9126b068fee2cf77917508eac6dfd5affae6d39.mp3":[{"id":"PPT_6f42171301964649","audioId":"PPT_6f42171301964649","title":"Book 2 · Unit 6 · RW · READING 1","subtitle":"READING 1 · source slide 54","duration":225.57,"cues":[{"start":0,"end":1.28,"text":"Home.","coverage":1},{"start":2.04,"end":3.16,"text":"About us.","coverage":1},{"start":4.06,"end":4.56,"text":"News.","coverage":1},{"start":5.54,"end":5.94,"text":"Quiz.","coverage":1},{"start":7.22,"end":8.32,"text":"Contact us.","coverage":1},{"start":9.08,"end":9.52,"text":"More.","coverage":1},{"start":10.58,"end":12.72,"text":"Are you ready for the world of work?","coverage":1},{"start":13.78,"end":15.68,"text":"Do you know what kind of job you want?","coverage":1},{"start":16.82,"end":18.84,"text":"Before you apply for a job,","coverage":1},{"start":19.3,"end":22.34,"text":"think about the different types of jobs that people do.","coverage":1},{"start":22.98,"end":25.38,"text":"There are four main types of jobs.","coverage":1},{"start":26.48,"end":28.22,"text":"One, jobs with people.","coverage":1},{"start":28.92,"end":29.56,"text":"Two,","coverage":1},{"start":30.04,"end":31.3,"text":"jobs with information.","coverage":1},{"start":32.4,"end":32.98,"text":"Three,","coverage":1},{"start":33.36,"end":34.44,"text":"jobs with things.","coverage":1},{"start":35.48,"end":36.12,"text":"Four,","coverage":1},{"start":36.72,"end":37.98,"text":"jobs with ideas.","coverage":1},{"start":39.06,"end":41.6,"text":"What kind of work would be best for you?","coverage":1},{"start":42.2,"end":46.08,"text":"Take our quiz and find out about the kind of work you would enjoy.","coverage":1},{"start":46.94,"end":48,"text":"For each question,","coverage":1},{"start":48.46,"end":50.48,"text":"choose the best answer for you.","coverage":1},{"start":50.74,"end":51.9,"text":"A, B,","coverage":1},{"start":52.2,"end":53.58,"text":"C, or D.","coverage":1},{"start":53.58,"end":59.36,"text":"Check your results and read the advice to find occupations you would like.","coverage":1},{"start":84.3,"end":85.1,"text":"Two,","coverage":1},{"start":86.06,"end":89.68,"text":"which sections of a news website do you look at first?","coverage":1},{"start":90.66,"end":91.12,"text":"A,","coverage":1},{"start":91.7,"end":94.22,"text":"advice page or letters to the editor.","coverage":1},{"start":95.14,"end":95.72,"text":"B,","coverage":1},{"start":96.2,"end":96.68,"text":"news.","coverage":1},{"start":97.2,"end":97.94,"text":"C,","coverage":1},{"start":98.38,"end":98.82,"text":"sport.","coverage":1},{"start":99.84,"end":100.2,"text":"D,","coverage":1},{"start":100.94,"end":101.22,"text":"TV,","coverage":1},{"start":101.62,"end":103.56,"text":"music, books, and art.","coverage":1},{"start":105.38,"end":106.18,"text":"Three,","coverage":1},{"start":107,"end":109.4,"text":"what do you like to do at an event?","coverage":1},{"start":110.5,"end":111.04,"text":"A,","coverage":1},{"start":111.44,"end":112.66,"text":"meet new people.","coverage":1},{"start":112.66,"end":113.92,"text":"B,","coverage":1},{"start":114.34,"end":116.42,"text":"discuss the latest news.","coverage":1},{"start":117.22,"end":117.66,"text":"C,","coverage":1},{"start":118.12,"end":120.12,"text":"help with the food and drinks.","coverage":1},{"start":120.9,"end":121.26,"text":"D,","coverage":1},{"start":121.68,"end":123.94,"text":"sing songs and tell jokes.","coverage":1},{"start":126.02,"end":129.5,"text":"Four, what do you prefer to do on a day off?","coverage":1},{"start":130.54,"end":131.06,"text":"A,","coverage":1},{"start":131.48,"end":133.14,"text":"have coffee with friends.","coverage":1},{"start":134.24,"end":134.72,"text":"B,","coverage":1},{"start":135.28,"end":137.4,"text":"organize your books and cupboards.","coverage":1},{"start":138.18,"end":138.62,"text":"C,","coverage":1},{"start":139.12,"end":141.58,"text":"work in the garden or clean the house.","coverage":1},{"start":141.58,"end":142.62,"text":"D,","coverage":1},{"start":143.14,"end":147.02,"text":"write poetry, make music, or draw pictures.","coverage":1},{"start":148.94,"end":150.5,"text":"Mostly A answers.","coverage":1},{"start":151.74,"end":152.76,"text":"You are friendly,","coverage":1},{"start":153.14,"end":155.22,"text":"kind, and interested in other people.","coverage":1},{"start":155.8,"end":158.16,"text":"You would enjoy a job working with children,","coverage":1},{"start":158.6,"end":161.84,"text":"with customers in a shop, or on a team with colleagues.","coverage":1},{"start":162.6,"end":164.52,"text":"Possible jobs are teacher,","coverage":1},{"start":165.1,"end":165.42,"text":"waiter,","coverage":1},{"start":165.94,"end":166.92,"text":"police officer.","coverage":1},{"start":168.92,"end":170.48,"text":"Mostly B answers.","coverage":1},{"start":170.48,"end":176.08,"text":"You are neat, you are good at planning, and you like learning new things.","coverage":1},{"start":176.76,"end":179.72,"text":"You would enjoy a job working with information.","coverage":1},{"start":180.46,"end":183.3,"text":"Possible jobs are university professor,","coverage":1},{"start":183.66,"end":184.68,"text":"computer programmer,","coverage":1},{"start":185.3,"end":185.88,"text":"librarian.","coverage":1},{"start":188.06,"end":189.88,"text":"Mostly C answers.","coverage":1},{"start":190.82,"end":192.04,"text":"You are practical,","coverage":1},{"start":192.46,"end":193.76,"text":"you are good at sports,","coverage":1},{"start":194.12,"end":196.14,"text":"and you like working with your hands.","coverage":1},{"start":196.72,"end":199.42,"text":"You would enjoy a job working with things.","coverage":1},{"start":199.42,"end":202.96,"text":"Possible jobs are construction worker,","coverage":1},{"start":203.3,"end":203.86,"text":"engineer,","coverage":1},{"start":204.48,"end":204.92,"text":"farmer.","coverage":1},{"start":207.1,"end":208.62,"text":"Mostly D answers.","coverage":1},{"start":209.84,"end":211.04,"text":"You are creative,","coverage":1},{"start":211.54,"end":214.68,"text":"you are good at music and art, and you like books.","coverage":1},{"start":215.48,"end":218.44,"text":"You would enjoy a job working with ideas.","coverage":1},{"start":219.36,"end":221.64,"text":"Possible jobs are artist,","coverage":1},{"start":222.22,"end":222.58,"text":"writer,","coverage":1},{"start":223.34,"end":223.66,"text":"singer.","coverage":1}],"file":"400277081942bfb8419e.js","track":0,"media":"../assets/media/6f42171301964649b084cefeb9126b068fee2cf77917508eac6dfd5affae6d39.mp3"}]};
window.SCHOOL_SOURCE_ANSWERS=[{"text":"1 What do you do with the things you own that you no longer want? Possible answer: I donate them, sell them or recycle them.","slide":5,"shape":"17","bookPage":"126"},{"text":"2 If something you own breaks, what do you do with it? Give examples. Possible answer: I try to repair it. For example, I would take a broken phone to a repair shop.","slide":5,"shape":"18","bookPage":"126"},{"text":"3 Would you buy something that somebody else owned before you? Why / Why not? Possible answer: Yes, if it is in good condition and costs less than a new item.","slide":5,"shape":"19","bookPage":"126"},{"text":"2  plastic shopping bags: Possible answers: carry toys in them; make something new from the plastic.","slide":7,"shape":"7","bookPage":"126"},{"text":"3  fish skin: Possible answers: eat it; make a belt from it.","slide":7,"shape":"8","bookPage":"126"},{"text":"1  Please mend this broken bag.","slide":15,"shape":"8","bookPage":"126"},{"text":"2  We can reuse the bottle instead of using it only once.","slide":15,"shape":"9","bookPage":"126"},{"text":"3  Factories can recycle plastic into new objects.","slide":15,"shape":"10","bookPage":"126"},{"text":"4  Do not throw away things that are still useful.","slide":15,"shape":"11","bookPage":"126"},{"text":"5  Wood and stone are building materials.","slide":15,"shape":"12","bookPage":"126"},{"text":"6  This shop makes money from waste.","slide":15,"shape":"13","bookPage":"126"},{"text":"Businesses in Cairo and Germany use plastic bottles, bags and boxes to make strong building materials. Businesses also turn fish skin into leather for shoes, bags and watches.","slide":18,"shape":"14","bookPage":"127"},{"text":"4 Watch the video again. Circle the correct answer.1 Rejoué sells toys that are new / not new.Answer: Rejoué sells toys that are not new.2 The prices of their toys are 30% / 40% cheaper.Answer: The prices of their toys are 40% cheaper.","slide":21,"shape":"13","bookPage":"127"},{"text":"4 Watch the video again. Circle the correct answer.3 Businesses always / often take materials from the world.Answer: Businesses often take materials from the world.4 A company in Tunisia recycles shoes and bags / hats.Answer: A company in Tunisia recycles shoes and bags.","slide":22,"shape":"13","bookPage":"127"},{"text":"1 Rejoué is a shop in Paris, France, that mends and sells toys.","slide":26,"shape":"5","bookPage":"127"},{"text":"2 Rejoué is a circular business.","slide":26,"shape":"13","bookPage":"127"},{"text":"3 They are different because they do not throw away their waste.","slide":26,"shape":"14","bookPage":"127"},{"text":"4 They do not throw away their waste.","slide":26,"shape":"15","bookPage":"127"},{"text":"5 Artists at Kenenti make old shoes exciting and sell them.","slide":27,"shape":"13","bookPage":"127"},{"text":"6 Tilegreen in Cairo makes building materials from plastic items.","slide":27,"shape":"14","bookPage":"127"},{"text":"7 In France, a company turns fish skin into sea leather, which is made into products.","slide":27,"shape":"15","bookPage":"127"},{"text":"6 What is the video mainly about? a Businesses can make money and help the planet by using waste to make things.","slide":29,"shape":"10","bookPage":"127"},{"text":"7 Work with a partner. Do you think the main speaker in the video supports the idea of “circular” businesses? How do you know?Possible answer: Yes. The speaker supports circular businesses because the ending says that going circular can make money and help the planet.","slide":31,"shape":"11","bookPage":"127"},{"text":"1 How are recycling and reusing things good for the planet? Give examples. Possible answer: Reusing and recycling reduce waste and the need for new materials. For example, reused bags replace some new bags.","slide":33,"shape":"14","bookPage":"127"},{"text":"2 Do you think there will be more circular businesses in the future? Possible answer: I think there will be more because businesses can earn money from materials that people throw away.","slide":33,"shape":"15","bookPage":"127"},{"text":"a  plan or arrange carefully","slide":46,"shape":"7","bookPage":"128"},{"text":"b  ask officially for something, often by writing","slide":47,"shape":"8","bookPage":"128"},{"text":"a  information that you find out from something, such as an exam, a scientific experimentor a medical test","slide":48,"shape":"7","bookPage":"128"},{"text":"b  a job or career","slide":49,"shape":"8","bookPage":"128"},{"text":"b  somebody you work with","slide":50,"shape":"8","bookPage":"128"},{"text":"a  people who buy things from a shop or business","slide":51,"shape":"7","bookPage":"128"},{"text":"2 Before you read, look at the text quickly. Circle the correct answer.1 What kind of text is it? b an online quiz2 What is the topic? a What would be your perfect job?","slide":64,"shape":"13","bookPage":"128"},{"text":"There are four main kinds of jobs: jobs with people, jobs with information, jobs with things and jobs with ideas.","slide":77,"shape":"13","bookPage":"130"},{"text":"The quiz helps you find out about the kind of jobs you might like.","slide":77,"shape":"14","bookPage":"130"},{"text":"After doing the quiz, read the advice to find jobs you might like.","slide":77,"shape":"15","bookPage":"130"},{"text":"5 Do the quiz. Circle your answers and count the letters you chose. Read the advice about jobs for you.Possible answer: I chose mostly a, and I agree because I enjoy helping people.","slide":80,"shape":"14","bookPage":"130"},{"text":"6 Do you agree or disagree with the advice? Why?Possible answer: I chose mostly b, but I would prefer a creative job because I enjoy making music.","slide":80,"shape":"15","bookPage":"130"},{"text":"1 What do you like to do in the evenings? c play sports or practise a hobby like a musical instrument or photography.","slide":90,"shape":"5","bookPage":"130"},{"text":"2 Which sections of a news website do you look at first?","slide":90,"shape":"16","bookPage":"130"},{"text":"2 Which sections of a news website do you look at first? a advice page or letters to the editor.","slide":90,"shape":"17","bookPage":"130"},{"text":"Mostly “b” answers: You are neat, you are good at planning and you like learning new things.","slide":90,"shape":"18","bookPage":"130"},{"text":"8 Read the text around the underlined words in the quiz. Choose the best definition.1 advice — b an opinion that somebody offers you about what you should do2 hobby — a an activity you do for fun","slide":93,"shape":"12","bookPage":"130"},{"text":"8 Read the text around the underlined words in the quiz. Choose the best definition.3 neat — a arranged well, with everything in its place4 section — b one of the parts that something is divided into","slide":94,"shape":"12","bookPage":"130"},{"text":"9 Who would be interested in the quiz? Why? Circle the correct answer. More than one answer is possible.Answer: b and c — a new university graduate and a secondary school student would be interested because both may be choosing a future career.","slide":100,"shape":"9","bookPage":"131"},{"text":"1. Passage A summary gap 1\nAnswer: forty","slide":103,"shape":"5","bookPage":null},{"text":"11. Paragraph A\nA. Checking results before claiming success\nB. Finding the causes of delays\nC. Hiring extra staff to increase production\nD. Protecting concentration while keeping a service open\nE. Stopping all contact with customers\nF. Keeping changes flexible for different needs\nG. Replacing repeated messages and meetings","slide":104,"shape":"5","bookPage":null},{"text":"I want to be an engineer. I can reach my goal by studying hard.","slide":117,"shape":"12","bookPage":"132"},{"text":"The company introduced a new smartphone which had much more memory than its other phones.","slide":117,"shape":"13","bookPage":"132"},{"text":"A lot of jobs were created by the new technology company. They now employ more than 1,000 people.","slide":117,"shape":"14","bookPage":"132"},{"text":"I work from home and my office is in the corner of the kitchen. It is small and I don’t have a lot of space for my desk and files.","slide":118,"shape":"15","bookPage":"132"},{"text":"I’m going to set up a new business selling clothes online.","slide":118,"shape":"16","bookPage":"132"},{"text":"The company needs to advertise its new tablet on the television so that more people know about it and want to buy it.","slide":118,"shape":"17","bookPage":"132"},{"text":"My sister runs her own restaurant. She started it five years ago and it’s doing really well.","slide":119,"shape":"15","bookPage":"132"},{"text":"My father set up an online business with his best friend. They were partners for over 20 years.","slide":119,"shape":"16","bookPage":"132"},{"text":"2 Look at the article on page 133. Notice the words in bold and the words around them. Read the title and write three things you think the article will mention.Possible answer 1: The article may explain what ChatGPT is.","slide":131,"shape":"11","bookPage":"132"},{"text":"2 Look at the article on page 133. Notice the words in bold and the words around them. Read the title and write three things you think the article will mention.Possible answer 2: The article may describe how OpenAI began and grew.","slide":131,"shape":"12","bookPage":"132"},{"text":"2 Look at the article on page 133. Notice the words in bold and the words around them. Read the title and write three things you think the article will mention.Possible answer 3: The article may discuss the benefits and concerns of AI technology.","slide":132,"shape":"11","bookPage":"132"},{"text":"ChatGPT is an artificial intelligence¹ (AI) technology. It can have an online conversationwith the person using it. It can understand questions and answer them in a way thatsounds ‘human’, and it can even say sorry when it makes a mistake.","slide":149,"shape":"8","bookPage":"133"},{"text":"ChatGPT is owned by a technology company called OpenAI. The company was set upby Elon Musk, Sam Altman and others in 2015. Their goal was to build safe AItechnology that could be used by everyone. Today, OpenAI employs 375 people.","slide":150,"shape":"8","bookPage":"133"},{"text":"The partners started a company that created the fastest-growing application² of all time.Now OpenAI wants to make more powerful AI technology. They believe that more use ofAI in the world is a good thing.","slide":151,"shape":"8","bookPage":"133"},{"text":"OpenAI grew very quickly. The company started with investments³ of $1 billion and in2016, less than a year later, it developed its first AI program, OpenAI Gym. In 2018 thecompany introduced the first version⁴ of GPT, which was the first time that a machinecould make sentences that sounded like they were written by a real person.","slide":152,"shape":"8","bookPage":"133"},{"text":"This was the same year that Elon Musk left OpenAI and the company announced it wasgoing to partner with Microsoft Corporation. The partnership meant OpenAI could domore research and share the results with the world. In 2020 OpenAI opened its office inSan Francisco. It shares the building with another business started by Elon Musk.","slide":153,"shape":"8","bookPage":"133"},{"text":"ChatGPT was introduced in November 2022, and it grew faster than any otherapplication. In only 2 months, 100 million people used it. About 13 million people usedChatGPT every day in January 2023, which is double the number who used it inDecember. Compare this to TikTok, which took about 9 months to get about 100 millionusers, and Instagram, which took about 2.5 years.","slide":154,"shape":"8","bookPage":"133"},{"text":"ChatGPT is free to use; however, in February 2023 OpenAI started toadvertise a subscription⁵.People who choose to pay $20 every month get faster answers to their questions.Some schools and teachers worry about students using ChatGPT to do their coursework.","slide":155,"shape":"8","bookPage":"133"},{"text":"A number of schools in America stopped teachers and students from using theapplication while they were at school. This shows that not everyone is happy about AItechnology and how fast it is growing. Some people think businesses like OpenAI are notthinking about the possible bad results of the things they are doing.","slide":156,"shape":"8","bookPage":"133"},{"text":"OpenAI is still working hard to make amazing AI that can help all people. In the future,they want to make AI programs that can do things like help doctors find cures fordiseases, find answers to difficult problems like climate change or help people to run theirbusinesses better.","slide":157,"shape":"8","bookPage":"133"},{"text":"Although some people worry that in the future AI will hurt people,OpenAI wants to make sure that AI will be safe for everyone to use and will make our liveseasier and more enjoyable.","slide":158,"shape":"8","bookPage":"133"},{"text":"4 Which heading best describes paragraph 2? Answer: b — The growth of OpenAI.","slide":168,"shape":"10","bookPage":"132"},{"text":"1 What is ChatGPT? It is an artificial intelligence technology that can have an online conversation and answer questions in a human-like way.","slide":180,"shape":"13","bookPage":"132"},{"text":"2 Who set up OpenAI? Elon Musk, Sam Altman and others set up OpenAI in 2015.","slide":180,"shape":"14","bookPage":"132"},{"text":"3 What was the goal of OpenAI? Its goal was to build safe AI technology that could be used by everyone.","slide":181,"shape":"13","bookPage":"132"},{"text":"4 What does OpenAI want to do in the future? It wants to make more powerful AI technology that can help people.","slide":181,"shape":"14","bookPage":"132"},{"text":"6 Read the text again. Correct the details.1 OpenAI has an office in San Francisco and employs 375 people.2 OpenAI introduced an AI program that could write sentences like a real person in 2018.","slide":192,"shape":"13","bookPage":"134"},{"text":"6 Read the text again. Correct the details.3 In two months, 100 million people used ChatGPT.4 ChatGPT grew faster than TikTok and Instagram.","slide":193,"shape":"13","bookPage":"134"},{"text":"1 Elon Musk, Sam Altman and others set up OpenAI in 2015.","slide":204,"shape":"15","bookPage":"134"},{"text":"2 OpenAI introduced ChatGPT in 2022.","slide":204,"shape":"16","bookPage":"134"},{"text":"3 OpenAI first advertised a paid option for ChatGPT in 2023.","slide":204,"shape":"17","bookPage":"134"},{"text":"8 In your opinion, does the writer think OpenAI is a good or bad company? Why?Possible answer: The writer presents OpenAI as mainly good because its AI can help people, doctors, climate-change research and businesses, although the article also includes concerns about AI.","slide":206,"shape":"11","bookPage":"134"},{"text":"9 Why, do you think, does the writer use the adjective “amazing” to describe AI technology in paragraph 4?Possible answer: The writer uses “amazing” to show that they see AI technology as impressive and able to help people solve difficult problems.","slide":210,"shape":"11","bookPage":"134"},{"text":"10 Which statement is closest to what the creators of OpenAI think? Answer: a — AI technology can make the world a better place.","slide":212,"shape":"10","bookPage":"134"},{"text":"Possible collocations: business opportunity; business plan; set up a business; run a business; business contact; business partner; expand a business.","slide":214,"shape":"10","bookPage":"135"},{"text":"1 a business plan — plan — N (the noun comes after business).","slide":216,"shape":"5","bookPage":"135"},{"text":"2 set up a business — set up — V (the verb comes before business).","slide":216,"shape":"12","bookPage":"135"},{"text":"3 run a business — run — V (the verb comes before business).","slide":216,"shape":"13","bookPage":"135"},{"text":"4 a business contact — contact — N (the noun comes after business).","slide":216,"shape":"14","bookPage":"135"},{"text":"2 Choose the correct business collocation.1 A business plan is a detailed document describing the future direction of a business.2 To expand a business means to make a business bigger.","slide":218,"shape":"12","bookPage":"135"},{"text":"2 Choose the correct business collocation.3 To run a business means to be in charge of a business.4 A business contact is a person you know because of your job.","slide":219,"shape":"12","bookPage":"135"},{"text":"4 Work in groups. Discuss the questions below.Possible answer: A business partner can share ideas, work and risk, but it is important to agree about decisions.","slide":221,"shape":"16","bookPage":"135"},{"text":"1 Is it better to run a business on your own or to have a business partner? Why?Possible answer: A business should expand when demand and money are strong; it should not expand when costs are too high or demand is uncertain.","slide":221,"shape":"17","bookPage":"135"},{"text":"2 When is it a good idea for a business to expand? When is it a bad idea?Possible answer: Yes. Business contacts can give advice, share information and create opportunities for future work.","slide":221,"shape":"18","bookPage":"135"},{"text":"5 Match the words (1–8) to their definitions (a–h).1 colleague — c somebody that you work with2 department — g part of a business or company3 employ — f to pay somebody to work or do a job for you4 employee — h a worker","slide":229,"shape":"12","bookPage":"136"},{"text":"5 Match the words (1–8) to their definitions (a–h).5 manager — e the person who organizes or leads a business6 office — d a place in a building where people work7 product — b something a business makes and sells8 software — a a program you use to control what a computer does","slide":230,"shape":"12","bookPage":"136"},{"text":"Important information for employees of Jenson Co.","slide":232,"shape":"7","bookPage":"136"},{"text":"I am pleased to tell you that we are moving into a bright new office in three months.We are also getting new software for our computers. We will have more space, so wecan employ more people.","slide":232,"shape":"8","bookPage":"136"},{"text":"I am very confident that these changes will help us sell more of our excellent products.It is exciting that our department continues to grow. You and your colleagues areresponsible for that.","slide":235,"shape":"6","bookPage":"136"},{"text":"Best,AlexandreSales manager","slide":235,"shape":"7","bookPage":"136"},{"text":"The company makes a profit each month.","slide":239,"shape":"6","bookPage":null},{"text":"The owner wants to attract more customers.","slide":239,"shape":"9","bookPage":null},{"text":"B–C–A","slide":240,"shape":"6","bookPage":null},{"text":"A–C–B","slide":241,"shape":"6","bookPage":null},{"text":"The owner is arranging products at a market stall. The display looks neat.","slide":242,"shape":"7","bookPage":null},{"text":"I think the display is useful. It helps a customer look at each product.","slide":242,"shape":"10","bookPage":null},{"text":"1. Bright Paper employed forty people.\nAnswer: TRUE","slide":248,"shape":"5","bookPage":null},{"text":"11. a replacement for two regular meetings\nA. Paragraph A\nB. Paragraph B\nC. Paragraph C\nD. Paragraph D\nE. Paragraph E","slide":249,"shape":"5","bookPage":null},{"text":"1. Passage B summary gap 1\nAnswer: two","slide":252,"shape":"5","bookPage":null},{"text":"11. Paragraph A\nA. Serving booked and unbooked customers fairly\nB. Replacing staff with online ordering\nC. Investigating queues and food waste\nD. Adapting the system after feedback\nE. Setting up a small pre-order trial\nF. Raising prices to pay for new equipment\nG. Assessing gains alongside costs and other influences","slide":253,"shape":"5","bookPage":null},{"text":"This product attracts customers from other towns.","slide":261,"shape":"6","bookPage":null},{"text":"The owner invests in new equipment.","slide":261,"shape":"9","bookPage":null},{"text":"B–A–C","slide":262,"shape":"6","bookPage":null},{"text":"Two people are arranging bowls and other products on a table. They are working on the display together. One may be the manager helping an employee.","slide":264,"shape":"7","bookPage":null},{"text":"The manager could explain where each product should go. The colleague could then arrange the smaller items. They could check the finished display together.","slide":265,"shape":"7","bookPage":null},{"text":"Important OpenAI events: 2015 — OpenAI was set up. 2018 — it introduced the first version of GPT. 2022 — it introduced ChatGPT.","slide":279,"shape":"16","bookPage":"137"},{"text":"2015 — OpenAI is set up. 2016 — OpenAI develops its first AI program. 2018 — Elon Musk leaves; OpenAI partners with Microsoft; OpenAI introduces GPT technology. 2020 — the San Francisco office opens. 2022 — ChatGPT is introduced. 2023 — a ChatGPT subscription service becomes available.","slide":283,"shape":"30","bookPage":"137"},{"text":"Event\nDate\nSummary\na\n2003\nEberhard and Tarpenning found Tesla.\nb\n2004\nElon Musk joins Tesla.\nc\n2006\nTesla receives a major investment.\nd\n2007\nTesla introduces the Roadster.","slide":299,"shape":"16","bookPage":"138"},{"text":"Event\nDate\nSummary\ne\n2008\nMusk takes over the company.\nf\n2010\nTesla partners with Toyota.\ng\n2021\nTesla moves its offices to Texas.","slide":300,"shape":"17","bookPage":"138"},{"text":"Event\nAdditional details\na  2003\nThe business is an electric car company.\nb  2004\nHe invests $6.5 million.\nc  2006\nThe investment is $40 million.","slide":301,"shape":"17","bookPage":"138"},{"text":"Event\nAdditional details\nd  2007\nThe introduction takes place in Santa Monica.\ne  2008\nMartin Eberhard resigned in 2007.\nf  2010\nThis is a partnership with another car company.\ng  2021\nTexas is the location named for the offices.","slide":302,"shape":"16","bookPage":"138"},{"text":"A: Why are you so late for work today? B: The bus broke down, so I walked to work. A: OK, but the meeting started 30 minutes ago.","slide":305,"shape":"12","bookPage":"139"},{"text":"B: Please tell them I am on my way to the meeting now. A: OK. Don’t forget your lunch. The meeting last week took three hours.","slide":306,"shape":"15","bookPage":"139"},{"text":"2 Circle the correct form of the verbs in the paragraph.The JLX company sells food to supermarkets and shops. In 2019, Martha Underwood set up the business. In 2020, the company did very well. In 2021, Martha Underwood employed three new people. The company expanded and opened new offices in Europe. Today, JLX is a very successful business.","slide":308,"shape":"15","bookPage":"139"},{"text":"In 2022, Tencent became one of the largest internet companies in the world.","slide":310,"shape":"12","bookPage":"140"},{"text":"Richard Branson sold Virgin Records in 1992.","slide":310,"shape":"13","bookPage":"140"},{"text":"In 2022, ChatGPT grew faster than any other application.","slide":311,"shape":"12","bookPage":"140"},{"text":"Indra Nooyi was born in India, graduated from Yale University and became the CEO of PepsiCo.","slide":311,"shape":"13","bookPage":"140"},{"text":"My company is called Smart Language, and it makes language apps for smartphones. I set up the company with a business partner in 2017. In 2018 my partner left to start her own business. In 2019 I introduced our first language app. In 2020 I employed 30 people. In 2022 the business grew, and we moved to a bigger office.","slide":314,"shape":"9","bookPage":"140"},{"text":"5 Put the words in order to make sentences.1 when / was two years old / The partners opened / the first one / a second restaurant / .Answer: The partners opened a second restaurant when the first one was two years old.2 moved to bigger / When the business / they / needed more / offices / employees, / .Answer: When the business needed more employees, they moved to bigger offices.","slide":318,"shape":"13","bookPage":"141"},{"text":"2 My brother set up a business when he was 16 years old.","slide":320,"shape":"13","bookPage":"141"},{"text":"3 When the company opened a new office, it employed 100 new people.","slide":320,"shape":"14","bookPage":"141"},{"text":"1 When I was twelve, I met my best friend.","slide":322,"shape":"13","bookPage":"141"},{"text":"2 I was fifteen when my family moved to a different city.","slide":322,"shape":"14","bookPage":"141"},{"text":"In 2005, three friends, Chad Hurley, Steve Chen and Jawed Karim, had an idea for an internet business. 1 a — They wanted to help people share videos on the internet. They created YouTube. Today, YouTube is the largest video sharing site on the internet, and it has over 1.5 billion users. YouTube’s first office was located in a simple room. 2 d — The room was located above a pizza restaurant in Menlo Park, California, in the US.","slide":328,"shape":"13","bookPage":"142"},{"text":"Their first video was posted in April 2005. It was called “Me at the Zoo”. 3 b — It showed Karim at the zoo talking about elephants. Within five months, over a million people saw the video. Businesses began to notice YouTube and wanted to advertise on the website. In July 2006, 65,000 new videos were posted every day. In November 2006, Google bought YouTube. 4 c — They paid the incredible price of $1.65 billion.","slide":329,"shape":"13","bookPage":"142"},{"text":"1 People who pay $20 per month get better and faster answers — b: a subscription service is available for ChatGPT.","slide":332,"shape":"7","bookPage":"142"},{"text":"2 It starts with $1 billion of investments — d: Elon Musk, Sam Altman and others set up OpenAI.","slide":332,"shape":"13","bookPage":"142"},{"text":"3 It grows faster than any other application — g: ChatGPT is introduced.","slide":332,"shape":"14","bookPage":"142"},{"text":"4 The partnership supports research and sharing results — e: Elon Musk leaves and OpenAI partners with Microsoft.","slide":332,"shape":"15","bookPage":"142"},{"text":"5 It shares a building with another Elon Musk company — a: the office in San Francisco opens.","slide":332,"shape":"5","bookPage":"142"},{"text":"6 A machine makes human-like sentences — f: OpenAI introduces GPT technology.","slide":332,"shape":"6","bookPage":"142"},{"text":"7 This happens less than one year after the company started — c: OpenAI develops its first AI program.","slide":333,"shape":"13","bookPage":"142"},{"text":"It now sells products across the country.","slide":339,"shape":"6","bookPage":null},{"text":"The business moved to a larger building last year.","slide":339,"shape":"9","bookPage":null},{"text":"C–A–B","slide":341,"shape":"6","bookPage":null},{"text":"In 2020, a designer rented this small office. She first worked there alone. A year later, she hired an assistant to help with orders. Today, the team designs posters for local shops.","slide":342,"shape":"7","bookPage":null},{"text":"The owner started the business at home in 2018. By 2021, she needed space for another employee. She then rented an office with a larger work area. The team now meets customers there.","slide":343,"shape":"7","bookPage":null}];
